"""Fixed-width legacy layouts, cyclic timestamps and namespace offsets."""
def register(topic,q,detail):
 def lesson(title,path,symbol,why,principle,use,reading,qa,cards):
  topic(title,'시간',path,symbol,why,principle,use,reading,*(q(*x) for x in qa),details=[detail(*x) for x in cards])
 lesson('옛32비트 시간 ABI·2038 경계와 필드 폭','include/vdso/time32.h','old_timespec32',
  '호환성 때문에 남아 있는 시간 형식과 새64비트 형식의 차이를 배웁니다.',
  'old_time32_t는 s32입니다. old_timespec32는 signed32초 tv_sec와 signed32나노초 tv_nsec를 담습니다. 초를 Unix epoch 기준으로 쓰면 최대2147483647은2038-01-19 03:14:07 UTC입니다. 초 필드를 더 큰 C 자료형으로 읽어도 저장된 ABI 폭이 자동 확대되지는 않습니다.',
  '오래된 ABI를 읽는 호환 경로에서 필드 폭과 변환 범위를 확인하고 새 인터페이스에는time64_t·timespec64 대체를 사용합니다. 이 구조체 선언은 입력 유효성을 스스로 검사하지 않습니다.',
  'typedef와 두 s32 필드·time32.h의새형식권장주석을연결하세요.',
  [('old_timespec32의초 필드 폭은?','signed32비트다','구조체에들어가면자동signed64비트다','typedef의s32가저장폭을결정합니다.이름이나읽는변수의폭으로ABI가바뀌지않습니다.'),('초를64비트변수에복사하면원래32비트시간표현범위도늘어나는가?','아니며원래필드의범위는그대로다','항상2038이후모든시각이원본에저장된다','변환된변수와외부저장형의표현가능범위는다릅니다.')],
  [('세기문제','2038은이signed32초epoch표현의경계입니다.모든Linux시간형식이같은때넘친다고설명하지않습니다.'),('정규화','ns필드가s32여도0..999999999정책은별도검사합니다.자료형만으로음수나잘못된범위를막지않습니다.')])
 lesson('옛timeval의마이크로초·timespec나노초와구분','include/vdso/time32.h','old_timeval32',
  '비슷한 두 필드 구조체라도 세부 시간 단위가 다른 점을 배웁니다.',
  'old_timeval32는old_time32_t초와s32 tv_usec를담고old_timespec32는tv_nsec를담습니다. 마이크로초1은나노초1000입니다. 같은s32필드폭이어도값을그대로복사하면1000배단위오류가날수있습니다. 헤더는형식선언만하며변환·정규화는호출경로의역할입니다.',
  '외부ABI의timeval/timespec종류와필드이름을확인합니다. 정규화된부분단위에서usec↔nsec변환시곱·절단정책과표현범위를확인합니다.',
  'tv_usec와tv_nsec선언을비교하세요.',
  [('123마이크로초는몇나노초인가?','123000나노초다','123나노초다','마이크로초를나노초로바꿀때1000을곱합니다.필드폭이같다고단위가같지는않습니다.'),('나노초999를마이크로초정수로자르면?','0이며나노초정밀도를잃는다','항상1로나머지없이변환된다','정수단위변환은1000보다작은부분을절단할수있습니다.반올림규칙은별도API정책입니다.')],
  [('legacy','두선언모두초는signed32이므로부분단위만바꿔초범위문제를해결하지않습니다.'),('전체헤더','이작은VDSO헤더의typedef·두구조체를각각해설합니다.다른oldtimex호환구현은별도입니다.')])
 lesson('시간 namespace offset·부호 있는초와unsigned나노초','include/vdso/time.h','timens_offset',
  '시간 관점을 옮기는 offset 자료형이 clock 값 자체와 다른 점을 배웁니다.',
  'timens_offset은 s64 sec와u64 nsec의두필드를갖습니다. offset을나타내는자료형이며clocksource를읽거나시각을설정하는코드가이선언안에없습니다. 나노초가unsigned라는점과caller가준수해야할정규화범위는별개입니다. 임의u64전체를유효부분초로가정하지않습니다.',
  '시간namespace와VDSO경로에서offset객체를볼때두필드의단위·부호·초범위를확인합니다. 동일객체의일관된관찰·실제더하기정책은호출코드와함께읽습니다.',
  '구조체의sec·nsec형식과이파일에함수가없는점을확인하세요.',
  [('nsec가u64이면모든값이유효부분초인가?','아니며정규화범위는사용경로의계약이다','자료형이모든값을자동정규화한다','자료형은저장가능범위입니다.사용가능한부분초값규칙은별도로확인합니다.'),('이구조체선언이직접하는일은?','offset필드의형식을정의한다','clocksource하드웨어를읽고시간을즉시설정한다','데이터배치정의와실제연산·시스템동작을구분합니다.')],
  [('atomic아님','두필드선언만으로같은시점의원자적snapshot이보장되지않습니다.'),('범위','VDSOtime.h전체선언을해설하지만namespace전체구현을이수업으로완성했다고하지않습니다.')])
 lesson('32비트 순환시각 비교·반 주기 이내 조건','include/linux/time.h','time_after32',
  '숫자가MAX에서0으로돌아가도가까운두시각의앞뒤를비교하는원리를배웁니다.',
  'time_after32(a,b)는u32의b-a차이를s32로보아음수인지검사합니다. time_before32(b,a)는인수를뒤집어같은조건을씁니다. 상대간격이2^31미만인범위에서순환하는32비트시각의앞뒤를결정합니다. 정확히반주기에서는두방향모두after가참일수있어전체숫자공간의일반순서가아닙니다.',
  '디스크·전송형식의32비트시각처럼폭을못바꾸는곳에서최대상대간격을확인합니다.초단위이면반주기가약68년이며모든값의무제한정렬비교함수로사용하지않습니다.',
  '두u32변환·차이·s32변환을wrap경계로따라가세요.',
  [('b=0xffffffff,a=0이면간격이1인순환시각의after는?','a가b이후로판정된다','0은작으므로반드시이전이다','u32의b-a가0xffffffff이고s32로-1입니다. wrap경계의가까운앞뒤를비교합니다.'),('차이가정확히2^31이면안전한일반순서인가?','아니며반주기경계는호출계약밖이다','모든방향에유일한대소가정해진다','두방향차이가같은부호비트가되어모호합니다.짧은상대간격전제가핵심입니다.')],
  [('단위','시간값단위가tick인지초인지에따라반주기의실제기간이다릅니다.'),('폭','모든인수를u32로자르므로더큰timestamp전체를보존하는비교가아닙니다.')])
 lesson('순환구간 포함·시작점에서의unsigned거리','include/linux/time.h','time_between32',
  'MAX를넘는구간안에값이있는지시작점기준거리로계산하는방법을배웁니다.',
  'time_between32(t,l,h)는(u32)(h-l)>=(u32)(t-l)입니다. l에서끝h까지의순환거리와l에서t까지의순환거리를비교하므로양끝을포함합니다. l=0xfffffffe,h=1이면구간은fe,ff,0,1입니다. fullwrap한바퀴와동일시하면안되며l==h는한점구간입니다.',
  '의도한구간을l에서h로향하는unsigned거리로정의합니다.짧은구간의before/after동치설명은반주기전제를확인하고반주기이상구간에서무조건같다고확대하지않습니다.',
  '두차이의u32wrap와>=를읽으세요.',
  [('l=0xfffffffe,h=1에서t=0은포함되는가?','포함된다','숫자0이l보다작으므로제외된다','시작점에서t까지2,끝까지3의unsigned순환거리이므로포함합니다.'),('l==h인식은모든한바퀴를포함하는가?','아니며t==l인한점만포함한다','같은끝점이면모든u32값을포함한다','끝까지거리가0입니다.0이상인거리중0만조건을통과합니다.')],
  [('반례','긴구간l0,h0xffffffff에서거리식은모든값을포함하지만signedafter/before식과동일하지않을수있습니다.'),('검산','거리기반참조모델로양끝·wrap·반주기경계와짧은구간동치를각각검사합니다.')])
 lesson('itimerspec 유효성·간격과만료값을모두검사','include/linux/time.h','itimerspec64_valid',
  '반복타이머의두시간값중하나만정상이어도안되는이유를배웁니다.',
  'itimerspec64_valid는it_interval과it_value에timespec64_valid를각각적용하고어느하나실패하면false입니다. valid는초음수와나노초부분범위를검사하며strict의ktime초상한검사는아닙니다. 유효성검사가실제로타이머를등록하거나0값의해제정책을실행하는것도아닙니다.',
  '입력구조체검사와실제timerAPI의clock·absolute/relative·해제계약을함께확인합니다.두필드의valid결과가true여야전체검사가통과합니다.',
  '두timespec검사와짧은회로||조건을읽으세요.',
  [('interval정상,value나노초=-1이면전체valid는?','false다','interval이정상이므로true다','두시간값을모두검사합니다. 나노초음수는timespec64_valid의범위를벗어납니다.'),('이검사가strict와같은초상한을적용하는가?','아니며기본valid두번이다','항상KTIME_SEC_MAX상한도검사한다','호출한함수이름을확인합니다. 기본형식검사와strict표현범위정책을구분합니다.')],
  [('0값','기본valid에서는0초0나노초가유효합니다. 실제타이머의0해제규칙은호출API에따릅니다.'),('전체범위','time.h의이세inline/macro만연결합니다.사용자메모리복사·clocksetting·호환변환은별도해설대상입니다.')])
